"""Expose original mouth identities before mesh-dependent interval attributes.

The complete surface, mouth records and acceptance outputs remain unchanged.
Only the private identity lookup uses this extra output; its coordinates and
mesh interval counts are deliberately not part of that output's contract.
"""
import hashlib

import bpy

OUTPUT='Mouth Identities'


def build(original):
    if not original.name.startswith(('Prochitecture Streets / Original compound profiled patch',
                                     'Prochitecture Streets / Original chain profiled patch')):
        raise ValueError('Identity output currently supports compound and logical surface groups')
    if 'Local frame' not in original.name:raise ValueError('Expected a framed surface')
    suffix=hashlib.sha256(original.name.encode()).hexdigest()[:16]
    name='Prochitecture Streets / Independent mouth identities v1 / '+suffix
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    frame=original.copy();frame.name=name
    call,=[n for n in frame.nodes if n.type=='GROUP' and 'Mouths' in n.outputs and 'Geometry' in n.outputs]
    raw=call.node_tree.copy();raw.name=name+' / Local construction'
    out=next(n for n in raw.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output)
    intervals,=[link.from_node for link in out.inputs['Mouths'].links]
    assert intervals.bl_idname=='GeometryNodeStoreNamedAttribute'
    assert intervals.inputs['Name'].default_value=='st_cs_intervals'
    source,=[link.from_socket for link in intervals.inputs['Geometry'].links]
    raw.interface.new_socket(name=OUTPUT,in_out='OUTPUT',socket_type='NodeSocketGeometry')
    raw.links.new(source,out.inputs[OUTPUT])
    # Copies retain all original interface identifiers. Appending an output
    # must not drop or redirect any of the original input/output bindings.
    def links():return sorted((s.name,l.from_node.name,l.from_socket.name) for s in call.inputs for l in s.links),sorted(
        (s.name,l.to_node.name,l.to_socket.name) for s in call.outputs for l in s.links)
    before=links();call.node_tree=raw;assert links()==before
    frame.interface.new_socket(name=OUTPUT,in_out='OUTPUT',socket_type='NodeSocketGeometry')
    out=next(n for n in frame.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output)
    frame.links.new(call.outputs[OUTPUT],out.inputs[OUTPUT])
    frame['st_separate_mouth_identities']=original.name
    return frame
